<?php require_role('student');$pageTitle='Supervision Sessions';$pageSubtitle='Request meetings and review formal feedback';$project=project_for_student((int)current_user()['id']);$sessions=$project?db_all("SELECT * FROM sessions WHERE project_id=? ORDER BY scheduled_at DESC",[$project['id']]):[];include __DIR__.'/../includes/layout_top.php'; ?>
<div class="split-grid"><section class="card"><div class="card-header"><div><h2>Request a session</h2><p>Provide a clear agenda before submitting.</p></div></div><?php if(!$project): ?><div class="callout">A project must be assigned before sessions can be requested.</div><?php else: ?><form method="post" action="<?= e(url('actions.php')) ?>"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="request_session"><div class="form-grid"><div class="form-group"><label>Preferred date and time</label><input type="datetime-local" name="scheduled_at" required></div><div class="form-group"><label>Meeting mode</label><select name="mode"><option value="physical">Physical</option><option value="online">Online</option><option value="hybrid">Hybrid</option></select></div><div class="form-group full"><label>Venue or meeting link</label><input name="venue_or_link" placeholder="Supervisor's office or video meeting link"></div><div class="form-group full"><label>Meeting agenda</label><textarea name="agenda" required placeholder="State the chapters, design issues or questions to be discussed."></textarea></div></div><button class="button" type="submit">Submit session request</button></form><?php endif; ?></section>
<section class="card"><div class="card-header"><div><h2>Session summary</h2><p>Formal records improve accountability.</p></div></div><div class="stats-grid" style="grid-template-columns:repeat(2,1fr)"><div class="stat-card"><div class="stat-label">Total</div><div class="stat-value"><?= count($sessions) ?></div></div><div class="stat-card"><div class="stat-label">Completed</div><div class="stat-value"><?= count(array_filter($sessions,fn($s)=>$s['status']==='completed')) ?></div></div></div><div class="callout">After each completed meeting, the supervisor records feedback, decisions and action items. These records remain available throughout the project lifecycle.</div></section></div>
<div class="card"><div class="card-header"><div><h2>Session history</h2><p>Requests, schedules and outcomes</p></div></div><?php if(!$sessions): ?><div class="empty-state">No session records are available.</div><?php else: ?><div class="table-wrap"><table><thead><tr><th>Date</th><th>Agenda</th><th>Mode / Venue</th><th>Status</th><th>Feedback and action items</th></tr></thead><tbody><?php foreach($sessions as $s): ?><tr><td><strong><?= e(format_date($s['scheduled_at'])) ?></strong></td><td><?= e($s['agenda']) ?></td><td><?= e(ucfirst($s['mode'])) ?><br><span class="muted"><?= e($s['venue_or_link']) ?></span></td><td><span class="badge <?= status_class($s['status']) ?>"><?= e($s['status']) ?></span></td><td><?php if($s['status']==='completed'): ?><strong>Feedback:</strong> <?= e($s['supervisor_feedback']) ?><br><strong>Actions:</strong> <?= e($s['action_items']) ?><br><strong>Next session:</strong> <?= e(format_date($s['next_session_date'])) ?><?php else: ?><span class="muted">Available after completion.</span><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></div>
